484→    function normalizeZip(raw) {
485→      var z = raw.trim().toUpperCase();
486→      z = z.replace(/\s+/g, '');        // collapse all spaces (UK: SW1A 2AA → SW1A2AA)
487→      z = z.replace(/-\d{4}$/, '');     // strip US ZIP+4 suffix (90210-1234 → 90210)
488→      return z;
489→    }
490→
491→    // Store the original button HTML so we can restore it exactly after loading
492→    var btnOriginalHtml = btn.innerHTML;
493→
494→    function setBtnLoading(loading) {
495→      btn.disabled = loading;
496→      if (loading) {
497→        btn.classList.add('zcc-btn--loading');
498→        // Replace entire button content with a lone spinner — no text overlap
499→        btn.innerHTML = '<span class="zcc-spinner" aria-hidden="true"></span>';
500→      } else {
501→        btn.classList.remove('zcc-btn--loading');
502→        // Restore original icon + label markup
503→        btn.innerHTML = btnOriginalHtml;
504→        // Keep button text in sync with config (merchant may have customised it)
505→        var labelEl = btn.querySelector('.zcc-btn-label');
506→        if (labelEl) labelEl.textContent = cfg.buttonText;
507→      }
508→    }
509→
510→    function checkZip() {
511→      var zip = normalizeZip(inp.value);
512→      inp.value = zip;  // Update the input field to show the normalized value (clean UX)
513→      if (!zip) { inp.focus(); return; }
514→
515→      setBtnLoading(true);
516→      res.innerHTML = "";
517→
518→      fetch(
519→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
520→          "&zip=" + encodeURIComponent(zip)
521→      )
522→        .then(function (r) {
523→          if (!r.ok) {
524→            // Non-2xx: try to parse JSON error body, fall back to status text
525→            return r.json().catch(function() {
526→              return { error: 'Server error (' + r.status + ')' };
527→            });
528→          }
529→          return r.json();
530→        })
531→        .then(function (data) {
532→          setBtnLoading(false);
533→
534→          // If the API returned an error object (no allowed field), treat as a
535→          // transient server error and show it in the result area rather than
536→          // falling through with undefined message text.
537→          if (data.error && data.allowed === undefined) {
538→            console.error('[Pinzo] API returned error:', data.error, '| API_BASE="' + API_BASE + '" SHOP="' + SHOP + '"');
539→            res.innerHTML = '<div class="zcc-result fail"><div class="zcc-result-icon">' + ICONS.xCircle + '</div><div class="zcc-result-content"><div class="zcc-result-message">Something went wrong. Please try again.</div></div></div>';
540→            try {
541→              sessionStorage.removeItem('zcc:valid');
542→              sessionStorage.removeItem('zcc:zip');
543→              window.dispatchEvent(new CustomEvent('zcc:validated', { detail: { valid: false, zip: zip } }));
544→            } catch(e) {}
545→            return;
546→          }
547→
548→          // Store validation result for cart page
549→          try {
550→            sessionStorage.setItem('zcc:valid', data.allowed ? 'true' : 'false');
551→            sessionStorage.setItem('zcc:zip', zip);
552→            sessionStorage.setItem('zcc:shop', SHOP);
553→            // Fire custom event for other scripts to listen to
554→            window.dispatchEvent(new CustomEvent('zcc:validated', {
555→              detail: { valid: data.allowed, zip: zip }
556→            }));
557→          } catch(e) { /* sessionStorage may be unavailable */ }
558→
559→          if (data.allowed) {
560→            var html = '<div class="zcc-result ok">' +
561→              '<div class="zcc-result-icon">' + ICONS.check + '</div>' +
562→              '<div class="zcc-result-content">' +
