729→  function joinWaitlist(zip, email, name, wBtn) {
730→    wBtn.disabled = true;
731→    var wBtnIcon = wBtn.querySelector('.zcc-wl-btn-icon');
732→    var wBtnLabel = wBtn.querySelector('.zcc-wl-btn-label');
733→    if (wBtnIcon) wBtnIcon.innerHTML = ICONS.spinner;
734→    if (wBtnLabel) wBtnLabel.textContent = 'Submitting\u2026';
735→    if (!wBtnIcon && !wBtnLabel) wBtn.textContent = 'Submitting\u2026';
736→
737→    var payload = { shop: SHOP, zip: zip, email: email };
738→    if (name) payload.name = name;
739→
740→    fetch(API_BASE + "/api/waitlist", {
741→      method: "POST",
742→      headers: { "Content-Type": "application/json" },
743→      body: JSON.stringify(payload),
744→    })
745→      .then(function (r) { return r.json(); })
746→      .then(function (data) {
747→        var wlEl = wBtn.closest(".zcc-wl");
748→        if (data.success) {
749→          if (wlEl) wlEl.innerHTML =
750→            '<div class="zcc-wl-success">' +
751→            '<span class="zcc-wl-success-icon">' + ICONS.checkmark + '</span>' +
752→            '<span>Your request has been submitted! We\u2019ll notify you when delivery is available.</span>' +
753→            '</div>';
